          '這些情況下，指引是呼叫緊急救護，並且切勿讓失去意識的人進食或喝水，以免嗆到。即使徵兆看似輕微，也不要強行餵食液體。若有醫師開立的升糖素，應依收到的指示使用。',
          '即使當事人在協助後好轉，仍值得在下次就診時說明這次發作。反覆發生可能意味著需要調整劑量或治療方案，而這只能由專業人員進行。記錄每次發作，有助於辨識規律。',
