          '偏見仍是對抗愛滋病毒時最大的障礙之一。它使人遠離檢驗與治療，而感染正是在這樣的空隙中悄悄前進。',
          '用正確的資訊而非臆測來談論這個議題，能保護所有人的健康，也讓帶有病毒者的生活更好。',
