          '另一個問題關於保險套：它仍然必要，因為也能預防其他性傳染病。檢驗與保險套是相輔相成的，不能互相取代。',
          '也常有人想知道陰性結果是否就此確定。若近期曾有暴露，須在免疫空窗期過後重複檢驗，該期間通常為 30 到 60 天。',
