          '在孕期發現感染，可以開始治療並採取措施，大幅降低傳染給嬰兒的機會。在妥善的治療與追蹤照護下，母親傳染給孩子的風險會降到很低的水準，嬰兒有很高的機會不帶有病毒。',
          '孕期檢驗並不是對母親行為的評價，也不是對其生活的懷疑。它是一項例行照護，目的在保護懷孕者與孩子雙方，也屬於全國產前所提供的檢驗之一。',
