          '陽性結果會安排開始治療，這在巴西由巴西公共衛生系統（SUS）免費提供。治療能阻止病毒複製、幫助恢復免疫力，並讓人維持良好的生活品質。',
          '無論哪一種結果，知道自己的狀況都比活在疑問中更好。了解狀況能為健康決定開路，也能保護身邊的人。',
